#include <stdio.h>
#include <stdlib.h>

/*
 * prog38_continued_fraction – reproduced from the original binary.
 *
 * Behaviour (matches the original program exactly):
 *   prog38_continued_fraction NUM DEN
 *
 *   * If fewer than two arguments are supplied → prints "NO_INPUT" and exits.
 *   * If either argument is not a valid decimal integer → prints "BAD_INPUT" and exits.
 *   * If DEN == 0 → prints "OUT_OF_RANGE" and exits.
 *   * If the continued‑fraction expansion would need more than 100 000 terms
 *     → prints "OUT_OF_RANGE" and exits.
 *   * Otherwise prints the regular (simple) continued‑fraction expansion of
 *     NUM/DEN in the mathematical notation:
 *         [a0; a1, a2, ...]
 *     followed by a newline.
 *
 * The strings used (including exact spelling and case) are taken from the
 * original binary.
 */

#define MAX_TERMS 100000   /* limit used by the original binary */

int main(int argc, char **argv)
{
    /* ---------- argument count check ---------- */
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    /* ---------- parse the two numbers ---------- */
    char *end1, *end2;
    long num = strtol(argv[1], &end1, 10);
    long den = strtol(argv[2], &end2, 10);

    if (*end1 != '\0' || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    if (den == 0) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ---------- compute the continued fraction ---------- */
    long terms[MAX_TERMS + 1];   /* +1 so we can detect overflow cleanly */
    int n = 0;                  /* number of terms stored */

    while (den != 0) {
        if (n > MAX_TERMS) {          /* too many terms */
            puts("OUT_OF_RANGE");
            return 0;
        }

        /* Ensure denominator is positive – the original program normalises the
         * sign before the Euclidean loop. */
        if (den < 0) {
            den = -den;
            num = -num;
        }

        long q = num / den;   /* integer quotient */
        long r = num % den;   /* remainder */

        /* Adjust for floor division when the remainder has the opposite sign.
         * This matches the mathematical definition of a simple continued
         * fraction and reproduces the behaviour of the original binary. */
        if (r != 0 && ((r < 0) != (den < 0))) {
            q -= 1;
            r += den;
        }

        terms[n++] = q;
        num = den;
        den = r;
    }

    /* ---------- output the fraction ---------- */
    putchar('[');
    if (n > 0) {
        printf("%ld", terms[0]);          /* a0 */
        if (n > 1) {
            printf("; %ld", terms[1]);    /* a1 */
            for (int i = 2; i < n; ++i) {
                printf(", %ld", terms[i]);   /* a2 … an */
            }
        }
    }
    puts("]");   /* puts adds the final newline */

    return 0;
}
